11	    static void validate(Graph graph) {
12	        Objects.requireNonNull(graph, "graph");
13	
14	        int vertexCount = graph.vertexCount();
15	        validateVertexCount(vertexCount);
16	
17	        List<Vertex> vertices = Objects.requireNonNull(graph.vertices(), "graph vertices");
18	        if (vertices.size() != vertexCount) {
19	            throw new IllegalArgumentException(
20	                    "Graph vertex list size does not match vertex count: " + vertices.size());
21	        }
22	
23	        validateVertices(vertices, vertexCount);
24	        validateNeighbors(graph, vertices, vertexCount);
25	    }
26	
27	    private static void validateVertexCount(int vertexCount) {
28	        if (vertexCount < 0) {
29	            throw new IllegalArgumentException("Vertex count must be non-negative.");
30	        }
31	    }
32	
33	    private static void validateVertices(List<Vertex> vertices, int vertexCount) {
34	        Set<Integer> seenIndexes = new HashSet<>();
35	
36	        for (Vertex vertex : vertices) {
37	            validateVertex(vertex, vertexCount, "Graph vertex");
38	            if (!seenIndexes.add(vertex.index())) {
39	                throw new IllegalArgumentException("Duplicate vertex index: " + vertex.index());
40	            }
41	        }
42	
43	        for (int expectedIndex = 0; expectedIndex < vertexCount; expectedIndex++) {
44	            if (!seenIndexes.contains(expectedIndex)) {
45	                throw new IllegalArgumentException("Missing vertex index: " + expectedIndex);
46	            }
47	        }
48	    }
49	
50	    private static void validateNeighbors(Graph graph, List<Vertex> vertices, int vertexCount) {
51	        for (Vertex vertex : vertices) {
52	            List<Vertex> neighbors =
53	                    Objects.requireNonNull(graph.neighborsOf(vertex), "neighbors for vertex " + vertex);
54	
55	            for (Vertex neighbor : neighbors) {
56	                validateVertex(neighbor, vertexCount, "Neighbor vertex");
57	            }
58	        }
59	    }
60	
61	    private static void validateVertex(Vertex vertex, int vertexCount, String label) {
62	        if (vertex == null) {
63	            throw new IllegalArgumentException(label + " must not be null.");
64	        }
65	        if (vertex.index() < 0 || vertex.index() >= vertexCount) {
66	            throw new IllegalArgumentException(label + " index out of bounds: " + vertex.index());
67	        }
68	    }
